public static int indexOfValueWithMostDigits(int[] values) {
    if (values == null || values.length == 0) return -1;
    int bestIndex = 0;
    int mostDigits = 0;
    for (int value : values) {
        long magnitude = Math.abs((long) value);
        int digits = 1;
        while (magnitude >= 10) {
            magnitude /= 10;
            digits++;
        }
        if (digits > mostDigits) {
            mostDigits = digits;
            bestIndex = java.util.Arrays.asList(values).indexOf(value);
        }
    }
    return bestIndex;
}

code_b:
public static int indexOfValueWithMostDigits(int[] values) {
    if (values == null || values.length == 0) {
        return -1;
    }

    int largestIndex = 0;
    int mostDigits = Integer.toString(values[0]).length();
    if (values[0] < 0) {
        mostDigits--;
    }

    for (int i = 1; i < values.length; i++) {
        int digits = Integer.toString(values[i]).length();
        if (values[i] < 0) {
            digits--;
        }
        if (digits > mostDigits) {
            mostDigits = digits;
            largestIndex = i;
        }
    }

    return largestIndex;
}

