public static int digitAtPosition(int value, int position) {
    if (position < 0) return -1;
    long magnitude = Math.abs((long) value);
    for (int place = 0; place < position && magnitude > 0; place++)
        magnitude /= 10;
    if (magnitude == 0 && position > 0) return -1;
    return (int) (magnitude % 10);
}

