public static int indexOfSmallestOddValue(int[] values) {
    if (values == null) return -1;
    int smallest = 0;
    int smallestIndex = -1;
    int i = 0;
    while (i < values.length) {
        if (values[i] % 2 != 0) {
            if (smallestIndex == -1) smallest = values[i];
            else if (values[i] < smallest) smallest = values[i];
            if (smallestIndex == -1 || values[i] < smallest) smallestIndex = i;
        }
        i++;
    }
    return smallestIndex;
}

