public static int countTargetCharactersAfterLastHash(String text, char target) {
    if (text == null || text.isEmpty()) return 0;
    int count = 0;
    int i = text.length() - 1;
    while (i >= 0 && text.charAt(i) != '#') {
        if (text.charAt(i) == target) count++;
        i--;
    }
    return count;
}

public static int countAlternatingParityRows(int[][] matrix) {
    if (matrix == null || matrix.length == 0) return 0;
    int count = 0;
    for (int[] row : matrix) {
        if (row == null || row.length == 0) continue;
        int i = 1;
        while (i < row.length) {
            if (row[i] % 2 == row[i - 1] % 2) break;
            i++;
        }
        if (i == row.length) count++;
    }
    return count;
}

code_b:
public static int countAlternatingParityRows(int[][] matrix) {
    if (matrix == null || matrix.length == 0) {
        return 0;
    }
    int count = 0;
    for (int i = 0; i < matrix.length; i++) {
        if (matrix[i] != null && matrix[i].length > 0) {
            boolean alternating = true;
            for (int j = 1; j < matrix[i].length; j++) {
                boolean previousIsEven = matrix[i][j - 1] % 2 == 0;
                boolean currentIsEven = matrix[i][j] % 2 == 0;
                if (previousIsEven == currentIsEven) {
                    alternating = false;
                    break;
                }
            }
            if (alternating) {
                count++;
            }
        }
    }
    return count;
}

