public static String classifyFirstDigit(String text) {
    if (text == null || text.isEmpty()) return "No input";
    char digit = text.charAt(0);
    if (digit >= '0' && digit <= '3') return "Low";
    else if (digit >= '4' && digit <= '6') return "Medium";
    else if (digit >= '7' && digit <= '9') return "High";
    else return "Not a digit";
}

