public static int countOccurrencesOfDigit(long number, int digit) {
    if (digit < 0 || digit > 9) return 0;
    int count = 0;
    do {
        if (number % 10 == digit) count++;
        number /= 10;
    } while (number != 0);
    return count;
}

code_b:
public static int countOccurrencesOfDigit(long number, int digit) {
    if (digit < 0 || digit > 9) {
        return 0;
    }

    if (number == 0) {
        return digit == 0 ? 1 : 0;
    }

    int count = 0;
    while (number != 0) {
        if (Math.abs(number % 10) == digit) {
            count++;
        }
        number /= 10;
    }
    return count;
}

