public static String httpStatusLabel(int status) {
    String label;
    switch (status) {
        case 200: label = "OK"; break;
        case 201: label = "Created"; break;
        case 301: label = "Moved permanently"; break;
        case 400: label = "Bad request"; break;
        case 403: label = "Forbidden"; break;
        case 404: label = "Not found"; break;
        case 500: label = "Internal server error"; break;
        default: label = ""; break;
    }
    if (!label.isEmpty()) return label;
    if (status < 100 || status > 599) return "Invalid";
    else if (status >= 200 && status < 300) return "Successful";
    else if (status < 200) return "Informational";
    else if (status < 400) return "Redirection";
    else if (status < 500) return "Client error";
    return "Server error";
}
